<?php
class HostController extends Controller{private function model(){require_once __DIR__.'/../models/Host.php';return new Host();}public function index(){require_role(['Admin','Host']);$hosts=$this->model()->all();$this->view('hosts/index',compact('hosts'));}public function create(){require_role(['Admin']);require_once __DIR__.'/../models/User.php';$users=(new User())->all();$this->view('hosts/form',['host'=>null,'users'=>$users,'action'=>url('hosts/store')]);}public function store(){verify_csrf();require_role(['Admin']);$this->model()->create(['user_id'=>$_POST['user_id'],'company_name'=>$_POST['company_name'],'contact_person'=>$_POST['contact_person'],'license_number'=>$_POST['license_number'],'is_verified'=>isset($_POST['is_verified'])?1:0]);Session::flash('success','Host created.');$this->redirect('hosts');}public function edit(){require_role(['Admin']);require_once __DIR__.'/../models/User.php';$host=$this->model()->find($_GET['id']);$users=(new User())->all();$this->view('hosts/form',['host'=>$host,'users'=>$users,'action'=>url('hosts/update?id='.$_GET['id'])]);}public function update(){verify_csrf();require_role(['Admin']);$this->model()->update($_GET['id'],['company_name'=>$_POST['company_name'],'contact_person'=>$_POST['contact_person'],'license_number'=>$_POST['license_number'],'is_verified'=>isset($_POST['is_verified'])?1:0]);Session::flash('success','Host updated.');$this->redirect('hosts');}public function delete(){require_role(['Admin']);$this->model()->delete($_GET['id']);Session::flash('success','Host deleted.');$this->redirect('hosts');}}
